// === Tab: mySketch ===
// Perlin Noise https://www.openprocessing.org/sketch/688380
// author: Anya Name

let nums = 150;
let num_clust =15; //originally 10
let strokeR = 1;
let alphaR = 70; //originally 100
let noiseScale = 300.0; 
let theta;
let posx = [];
let posy = [];
let r = [];
let particles = [];

let pCnt = 0;

function setup(){
	//createCanvas(displayWidth,displayHeight);
	createCanvas(900,500); 
	background(color('#C477BA'));
    theta = float(-PI/2);

	// init clusters
	for(let i=0; i<num_clust;i++){
		posx[i]= int(random(width));
		posy[i]= int(random(height));
		//r[i] = int(random(50,120));
		r[i] = int(random(50,100));
	}

	// init particles
	for(let j=0; j<num_clust;j++){
        particles[j] = [];
		for(i = 0; i < nums; i++){  
			particles[j][i] = new Particle(posx[j]+r[j]*sin(theta),posy[j] + r[j]*cos(theta));
			theta +=TWO_PI/nums;
		}
	}

	for(j=0; j<num_clust;j++){
		for (i = 1; i < 120; i++) {
			fill(lerpColor(color('#D8B1D8'),color('#000000'),i/120.0)); 
			noStroke();
			ellipse(posx[j],posy[j], 2*r[j]-(i), 2*r[j]-(i));
		}
	}
}

function draw(){
	for(let j=0; j<num_clust;j++){
		for(let i = 0; i < nums; i++){
			particles[j][i].move(); 
			particles[j][i].display(strokeR);
		}       
	}
}

class Particle{
	constructor(px,py){
		this.c = color(0,alphaR);
		this.speed=0.4;
		this.dir = createVector(0, 0);
		this.pos = createVector(px, py);
	} 

	move(){
		let angle = float(noise(this.pos.x/noiseScale, this.pos.y/noiseScale)*TWO_PI);
		this.dir.x = sin(angle);
		this.dir.y = cos(angle);
		this.dir.mult(this.speed);
		this.pos.add(this.dir);
	}

	display(r){ 
		fill(this.c);
		ellipse(this.pos.x, this.pos.y, r, r);
	}
 }

